import html
from itertools import combinations

from core.kbju import parse_kbju
from core.scoring import score

KBJU_PROPERTY = "Пищевая и энергетическая ценность в 100 г"
MIN_WINNER_GAP = 0.03


def describe_product(item: dict) -> dict:
    """Товар ВкусВилла (из поиска или product_details) → id, название, КБЖУ, скор."""
    value = next((p["value"] for p in item.get("properties", []) if p["name"] == KBJU_PROPERTY), None)
    if value is None:
        raise ValueError(f"у товара {item['id']} нет КБЖУ: выбери другой товар")
    kbju = parse_kbju(value)
    return {
        "id": item["id"],
        "xml_id": item["xml_id"],
        "name": html.unescape(item["name"]),
        "kbju": {"protein": kbju.protein, "fat": kbju.fat, "carbs": kbju.carbs, "kcal": kbju.kcal},
        "score": score(kbju),
    }


def _single_winner(products: list[dict]) -> dict | None:
    first, second = sorted(products, key=lambda p: p["score"], reverse=True)[:2]
    # Скоры округлены до 3 знаков; без round 0.141 - 0.111 во float меньше 0.03.
    if round(first["score"] - second["score"], 3) < MIN_WINNER_GAP:
        return None
    return first


def check_query(query: str) -> None:
    """Проверка запроса до похода в поиск ВкусВилла."""
    if not query.strip():
        raise ValueError("поисковый запрос пуст: укажи категорию, например «творог»")


def build_round(query: str, items: list[dict]) -> dict:
    check_query(query)
    candidates = {}
    for item in items:
        if item["id"] in candidates:
            continue
        try:
            candidates[item["id"]] = describe_product(item)
        except ValueError:
            continue
    for triple in combinations(candidates.values(), 3):
        winner = _single_winner(list(triple))
        if winner is None:
            continue
        losers = [p for p in triple if p is not winner]
        # Позиция победителя зависит от id, а не от скора и порядка поиска.
        position = sum(p["id"] for p in triple) % 3
        products = losers[:position] + [winner] + losers[position:]
        return {"query": query, "products": products, "winner_id": winner["id"]}
    raise ValueError(
        f"по запросу «{query}» не нашлось трёх товаров с КБЖУ, где лучший опережает "
        f"второго на {MIN_WINNER_GAP} и больше: попробуй другой запрос — другую категорию или более общее название, например «творог»"
    )


def check_round(ids: list[int], choice_id: int) -> None:
    """Проверка id раунда и выбора до запросов за товарами."""
    if len(ids) != 3:
        raise ValueError(f"в раунде должно быть ровно 3 товара, передано {len(ids)}")
    if len(set(ids)) != 3:
        raise ValueError(f"товары в раунде повторяются: {ids}, нужны 3 разных id")
    if choice_id not in ids:
        raise ValueError(f"выбранный товар {choice_id} не из раунда: выбери один из {ids}")


def judge_round(products: list[dict], choice_id: int) -> dict:
    check_round([p["id"] for p in products], choice_id)
    described = [describe_product(p) for p in products]
    best = max(p["score"] for p in described)
    leaders = [p for p in described if p["score"] == best]
    if len(leaders) > 1:
        raise ValueError(f"у товаров {[p['id'] for p in leaders]} одинаковый лучший скор: победителя нет")
    winner_id = leaders[0]["id"]
    return {
        "correct": choice_id == winner_id,
        "winner_id": winner_id,
        "scores": {p["id"]: p["score"] for p in described},
    }
import json
import urllib.request
from typing import Callable

MCP_URL = "https://mcp.vkusvill.ru/mcp"
# QRATOR перед mcp.vkusvill.ru отвечает 403 на User-Agent «Python-urllib/…».
_USER_AGENT = "looksmax-grocery/1.0"

Transport = Callable[[dict], dict]


def http_transport(payload: dict, url: str = MCP_URL) -> dict:
    request = urllib.request.Request(
        url,
        data=json.dumps(payload).encode("utf-8"),
        headers={
            "Content-Type": "application/json",
            "Accept": "application/json, text/event-stream",
            "User-Agent": _USER_AGENT,
        },
    )
    with urllib.request.urlopen(request, timeout=20) as response:
        return json.loads(response.read().decode("utf-8"))


class VkusVillClient:
    def __init__(self, transport: Transport = http_transport):
        self._transport = transport

    def search(self, q: str, limit: int) -> list[dict]:
        data = self._call("vkusvill_products_search", {"q": q, "limit": limit, "mode": "full"})
        return data["items"]

    def product_details(self, product_id: int) -> dict:
        return self._call("vkusvill_product_details", {"id": product_id})

    def cart_link(self, xml_ids: list[int]) -> str:
        if not xml_ids:
            raise ValueError("корзина пуста: передай хотя бы один xml_id товара")
        products = [{"xml_id": xml_id, "q": 1} for xml_id in xml_ids]
        return self._call("vkusvill_cart_link_create", {"products": products})["link"]

    def _call(self, tool: str, arguments: dict):
        response = self._transport(
            {
                "jsonrpc": "2.0",
                "id": 1,
                "method": "tools/call",
                "params": {"name": tool, "arguments": arguments},
            }
        )
        if "error" in response:
            raise ValueError(f"ВкусВилл отклонил запрос {tool}: {response['error']['message']}")
        result = response["result"]
        text = "".join(part["text"] for part in result["content"] if part["type"] == "text")
        if result.get("isError"):
            raise ValueError(f"ВкусВилл вернул ошибку {tool}: {text}")
        body = json.loads(text)
        if not body["ok"]:
            raise ValueError(f"ВкусВилл вернул ошибку {tool}: {body['error']['message']}")
        return body["data"]
from core.kbju import Kbju


def score(kbju: Kbju) -> float:
    if kbju.kcal <= 0:
        raise ValueError("ккал должны быть больше нуля")
    return round(kbju.protein * 4 / kbju.kcal, 3)


def coins_for_answer(correct: bool, streak: int) -> int:
    """streak — длина серии верных ответов подряд, включая текущий."""
    if streak < 0:
        raise ValueError("длина серии не может быть отрицательной")
    if correct and streak < 1:
        raise ValueError("при верном ответе серия должна быть не меньше 1")
    if not correct:
        return 0
    if streak >= 3:
        return 15
    return 10


# Нижняя граница процента -> ранг, от старшего к младшему.
_RANKS = [
    (100, "true adam"),
    (80, "chad"),
    (70, "chadlite"),
    (60, "HTN"),
    (50, "MTN"),
    (40, "LTN"),
    (20, "sub5"),
    (0, "sub3"),
]


def rank(correct_count: int) -> str:
    if not 0 <= correct_count <= 10:
        raise ValueError("число верных ответов должно быть от 0 до 10")
    percent = correct_count / 10 * 100
    for threshold, name in _RANKS:
        if percent >= threshold:
            return name
import re
from dataclasses import dataclass

_NUMBER = r"(\d+(?:[.,]\d+)?)"
_PATTERNS = {
    "protein": re.compile(r"белки\s+" + _NUMBER),
    "fat": re.compile(r"жиры\s+" + _NUMBER),
    "carbs": re.compile(r"углеводы\s+" + _NUMBER),
    "kcal": re.compile(_NUMBER + r"\s*ккал"),
}
_LABELS = {"protein": "белки", "fat": "жиры", "carbs": "углеводы", "kcal": "ккал"}
# У мяса и рыбы ВкусВилл не пишет углеводы, а иногда и жиры: «белки 16 г, жиры 14 г, ; 190 ккал».
_OPTIONAL = {"fat", "carbs"}


@dataclass(frozen=True)
class Kbju:
    protein: float
    fat: float
    carbs: float
    kcal: float


def parse_kbju(value: str) -> Kbju:
    block = value.split("<br>", 1)[0]
    numbers = {}
    for field, pattern in _PATTERNS.items():
        match = pattern.search(block)
        if match is None and field in _OPTIONAL:
            numbers[field] = 0.0
            continue
        if match is None:
            raise ValueError(f"в строке КБЖУ нет значения «{_LABELS[field]}»: {block!r}")
        numbers[field] = float(match.group(1).replace(",", "."))
    if numbers["kcal"] <= 0:
        raise ValueError(f"ккал в строке КБЖУ должны быть больше нуля: {block!r}")
    return Kbju(**numbers)
from mcp.server.fastmcp import FastMCP

from core.rounds import build_round as make_round
from core.rounds import check_query, check_round, describe_product
from core.rounds import judge_round as judge
from core.vkusvill import VkusVillClient

SEARCH_LIMIT = 10


def create_server(client: VkusVillClient) -> FastMCP:
    # INFO пишет в stderr строку на каждый запрос; в логах клиента это только шум.
    mcp = FastMCP("looksmax", log_level="WARNING")

    @mcp.tool()
    def score_product(product_id: int) -> dict:
        """Looksmax-скор товара ВкусВилла: id, название, КБЖУ на 100 г и белки × 4 / ккал."""
        return describe_product(_product_details(client, product_id))

    @mcp.tool()
    def build_round(query: str) -> dict:
        """Раунд из поиска ВкусВилла: 3 товара одной категории с КБЖУ и скором и winner_id."""
        check_query(query)
        return make_round(query, client.search(query, SEARCH_LIMIT))

    @mcp.tool()
    def judge_round(product_ids: list[int], choice_id: int) -> dict:
        """Судит выбор игрока: верно ли, winner_id и скоры трёх товаров по их product_details."""
        check_round(product_ids, choice_id)
        return judge([_product_details(client, product_id) for product_id in product_ids], choice_id)

    return mcp


def _product_details(client: VkusVillClient, product_id: int) -> dict:
    if product_id <= 0:
        raise ValueError(f"product_id должен быть больше нуля, передано {product_id}: возьми id товара из поиска")
    try:
        return client.product_details(product_id)
    except ValueError as e:
        raise ValueError(f"товар {product_id} не найден во ВкусВилле ({e}): проверь product_id") from e


if __name__ == "__main__":
    create_server(VkusVillClient()).run("stdio")
# Writing Good Tests

**Load this reference when:** writing or changing tests, adding mocks, or
adding cleanup/helper methods for tests.

## Overview

A test exists to catch a specific break. Two principles govern everything
here:

```
1. Every test names the break it catches
2. Every test exercises the real thing
```

Strict TDD produces both naturally: a test written first and watched
failing against real code has already proven it can fail, and only earns
a mock when the real dependency proves slow or external.

## Principle 1: Name the Break

Before writing the test body, answer: **what production change should
make this test fail — and is that change a bug or a decision?** A test
earns its place by catching a wrong branch, missing side effect, wrong
argument, boundary case, or broken contract.

**Derive expectations independently.** Use literals and hand-checked
fixtures; table-driven tests with literal `want` values are the preferred
shape. An expectation computed by the code under test — or its helpers —
passes no matter what that code does:

```typescript
// ❌ Mirror assertion: the same builder computes both sides — always true
const expected = buildSearchQuery({ tag: 'urgent' });
expect(buildSearchQuery({ tag: 'urgent' })).toBe(expected);

// ✅ Hand-derived literal
expect(buildSearchQuery({ tag: 'urgent' })).toBe('tag:"urgent"');
```

**No change detectors.** If only intentional decisions can fail a test —
a constant's value, exact message wording, private structure — it fires
on redesign and sleeps through bugs. Test the behavior that depends on
the decision: not `expect(MAX_RETRIES).toBe(5)` but "a failing call is
retried 5 times and the 6th attempt never happens."

**Behavior, not text.** Asserting that a script, skill, or config
contains an exact line proves only that the source is the source. Run
scripts against controlled inputs and assert outputs, side effects, or
exit codes. Documents that instruct agents are tested by the consuming
agent's behavior (superpowers:writing-skills); prose for humans earns no
test at all.

**Your code, not the framework.** Test the contract your code makes at
its boundaries — the route you register, the query you emit, the payload
you produce. Upstream mechanics are their maintainers' tests to write
(the classic: asserting your router invokes a registered handler — that
is the framework's test, not yours). When upstream behavior genuinely
surprised you, write one narrow characterization test naming the
assumption. The same boundary applies inside your code: constructors,
getters, constants, and trivial forwarding earn tests only when they
validate, normalize, default, derive, enforce, or cause side effects —
otherwise assert the first consumer-visible result that depends on them.

### Gate Function

```
BEFORE writing the test body:
  Name the production change that would make this test fail.

  Cannot name one            → redesign around an observable behavior
  "The source text changed"  → run the artifact and assert its effects
  Only intentional decisions → change detector; test the behavior
                               that depends on the decision

  Confirm the expected value is derived without the code under test.
  IF it reuses the code's logic or helpers:
    Replace it with a literal or hand-checked fixture
```

